  _u = `Nhập URL sự kiện để chọn`,
  vu = `Nhập URL sự kiện đầy đủ rồi chọn từ menu tự động điền. Sự kiện phải hiển thị công khai để được thêm vào.`,
  yu = `Đăng lại sự kiện`,
  bu = `Đăng lại`,
  xu = `Đăng lại là nhắc tới sự kiện trong trung tâm tin tức trên dòng thời gian của các nhóm được chọn bên dưới. Sau đây là danh sách nhóm cộng đồng và ứng dụng khác mà bạn có thể đăng lại sự kiện này. Chọn một hoặc nhiều nhóm để thực hiện.`,
