  Nu = `Cần Valve xét duyệt trước khi có thể đặt trang này thành công khai`,
  Pu = `Sự kiện ưu đãi này vẫn đang chờ Valve chấp thuận`,
  Fu = `Vui lòng dùng nút bên phải để gửi trang của bạn đi xét duyệt, ít nhất 7 ngày trước thời điểm muốn đăng, để đảm bảo đủ thời gian cho quá trình đánh giá/chấp thuận và bất kỳ thay đổi cần thiết.`,
  Iu = `Đội ngũ Steam sẽ liên hệ qua phiếu hỗ trợ Steamworks nếu thấy trang của bạn cần có thay đổi nào. Bạn có thể xem phiếu hỗ trợ Steamworks, và thêm chú thích nếu cần thiết, bằng cách nhấn nút bên phải.`,
  Lu = `Đánh dấu trang là đã chấp thuận sẽ cho phép đối tác đăng và chạy ưu đãi`,
  Ru = `Yêu cầu xét duyệt...`,
  zu = `Yêu cầu xét duyệt`,
  Bu = `Tạo phiếu yêu cầu xét duyệt chấp thuận phát hành trang ưu đãi. Thực hiện điều này khi trang ưu đãi của bạn đã có tranh ảnh hoàn tất và bao gồm tất cả trò chơi bạn muốn trưng bày.`,
  Vu = `Thao tác này sẽ tạo phiếu hỗ trợ Steamworks yêu cầu Valve xét duyệt trang bán hàng của bạn. Chỉ nên thực hiện khi bạn đã chốt ảnh và thông điệp cũng như hoàn thiện danh sách trò chơi.`,
  Hu = `Vui lòng đảm bảo tên và mục đích sự kiện được mô tả rõ ràng gần phía đầu trang. Đối với mục trưng bày, bạn có thể cần phần văn bản trên đầu trang để mô tả nội dung trưng bày và cách thức hoạt động.`,
  Uu = `Sẽ khóa trang ưu đãi sau khi đã xét duyệt xong. Nếu bạn cần thực hiện thay đổi sau xét duyệt hay một khi sự kiện bắt đầu, vui lòng mô tả trong phần bình luận các thay đổi này kèm lý do không thể điều chỉnh trước xét duyệt.`,
  Wu = `Không bắt buộc: Thông tin bạn muốn gửi đến người xét duyệt`,
  Gu = `Chọn đối tác gồm thành viên cũng có thể truy cập vào phiếu yêu cầu`,
  Ku = `Không bắt buộc: Nếu chọn, các thành viên khác của đối tác có thể truy cập và phản hồi vào phiếu này. Mặc định chỉ bạn có thể đọc, cập nhật, và trả lời phiếu đã tạo.`,
  qu = `Không thể tạo phiếu, vui lòng thử lại sau`,
  Ju = `Không thể tạo phiếu hỗ trợ mới; đã tồn tại phiếu loại này. Vui lòng hoàn tất đánh giá trang ưu đãi còn lại trước khi gửi phiếu hỗ trợ hoặc cập nhật phiếu hiện có để bao gồm cả đánh giá của trang này.`,
