  aB = `Demo`,
  oB = `Nhạc`,
  sB = `Đây là số tiền bạn sẽ tiết kiệm khi mua sản phẩm trong bộ cùng nhau`,
  cB = `Không những được giảm giá khi mua cả bộ, một hoặc nhiều sản phẩm trong bộ này còn có khuyến mãi ngắn hạn, làm cho tổng mức giảm giá lớn hơn`,
  lB = `Bạn đã sở hữu một phần của bộ sản phẩm bao gồm trò chơi này, vậy nên hoàn thành bộ sẽ ít tốn chi phí hơn`,
  uB = `Bạn đã sở hữu một phần của bộ sản phẩm bao gồm trò chơi này, thêm vào đó, còn có khuyến mãi ngắn hạn nữa`,
  dB = `Khuyến mãi ngắn hạn trên giá gốc`,
  fB = `Xem buổi phát trực tuyến trong %1$s phút và nhận vật phẩm từ nhà phát triển khi sự kiện kết thúc!`,
  pB = `Xem buổi phát trực tuyến trong %1$s phút và nhận vật phẩm từ %2$s khi sự kiện kết thúc!`,
  mB = `Xem buổi phát trực tuyến trong %1$s giờ và nhận vật phẩm từ nhà phát triển khi sự kiện kết thúc!`,
  hB = `Xem buổi phát trực tuyến trong %1$s giờ và nhận vật phẩm từ %2$s khi sự kiện kết thúc!`,
