  DB = `Sự kiện bên thứ ba này được tổ chức bởi %1$s`,
  OB = `Sự kiện bên thứ ba này được tổ chức bởi %1$s và %2$s`,
  kB = `Yêu cầu người tổ chức nhập thông tin bên thứ 3 tổ chức sự kiện này`,
  AB = `Khi đặt thành "true", người tổ chức sự kiện cần chỉ định ai là người chủ trì sự kiện. Sẽ được hiển thị trên trang ưu đãi để khách hàng nhìn thấy rõ ràng người tổ chức là ai, và tránh cho khách hàng nhầm lẫn rằng Valve đang tổ chức sự kiện đó.`,
  jB = `Xóa tất cả nhà tổ chức sự kiện đã nhập`,
  MB = `Bạn phải nhập thông tin mô tả tổ chức thực hiện sự kiện ưu đãi này.`,
