  jU = `Chương 2/4`,
  MU = `Chương 3/4`,
  NU = `Chương 4/4`,
  PU = `Ngọc Hoàng triệu tập muôn thú trong vương quốc chạy đua tới Thiên đình, tuyên bố 12 con vật về đích trước tiên sẽ được tôn vinh bằng một vị trí trong niên biểu mới.

Tý tinh quái vượt sông và có mặt ở Thiên đình đầu tiên. Chả thèm bơi, Tý ta cưỡi trên lưng anh Sửu cả tin - hấp tấp nhảy lên vườn thượng uyển của Ngọc Hoàng ngay khi cả hai đến gần bờ.

Sửu điềm đạm vượt sông một cách dễ dàng. Không bận tâm lắm đến kết quả cuộc đua, Sửu cũng khá ưng ý vì vị trí thứ nhất của Tý có công lớn của ảnh.`,
  FU = `Dần tự lực di chuyển quá thận trọng để vượt lên Sửu, nghĩ rằng về thứ ba cũng được rồi may là không thấp hơn.

Mão mau mắn nhận ra mình lạc trôi đâu đâu. Nhưng hay không bằng hên, nương nhờ vào gió, đã cuốn chàng ta đi đúng hướng.

Thìn với lợi thế trên cao thấy ngôi làng đằng xa xa đang lâm nguy, nên dĩ nhiên Thìn đã dừng lại để giúp đỡ - thậm chí tặng luôn Mão một luồng gió vượt sông. Danh dự quan trọng hơn thắng thua, Thìn cảm thấy an yên ở vị trí thứ năm.`,
  IU = `Tỵ ranh ma không muốn mất sức đường xa nên liền quấn vào vó chân Ngọ. Khi Ngọ đang băng băng về đích, Tỵ liền buông ra, theo đà vượt lên phía trước đủ xa để về đích thứ sáu, để lại Ngọ vẫn còn phi nước kiệu tới đích ở phía sau.`,
  LU = `Mùi, Thân và Dậu cả ba cùng nhau hợp sức nhưng quyết định để Mùi giữ vị trí thứ tám chung cuộc. Tiếp theo là Thân nghịch ngợm, còn Dậu oai vệ thì cán đích thứ mười, hãnh diện rằng thứ tự như thế là công bằng. 

Tuất ham chơi chỉ chú tâm nghịch nước xung quanh, cảm thấy hạng mười một cũng không tồi để đổi lấy niềm vui. 

Và bét bảng là Hợi, chốc chốc dừng ven đường để ăn bánh ngửi hoa - song đủ khôn khéo để biết mỗi con vật đều sẽ nhận được ân sủng riêng từ Ngọc Hoàng.`,
